raw:
{
  "spells": [
    {
      "id": "spell_water_01",
      "theory": "凝露术把稀薄魔力铺在杯壁的细密刻痕上，使刻痕比周围更冷，空气中的水汽便沿着纹路聚成水珠。空气越潮湿、杯壁越凉，出水越快。它只能利用已有水汽，不能凭空造水，因此干燥的室内或大风天几乎无效，所凝之水也未必洁净，须经煮沸或净水术处理方可饮用。",
      "casting": "用食指在杯壁外侧画一圈螺旋，指尖贴着刻痕缓缓注入魔力，直到第一颗水珠沿螺旋滑下。",
      "failure": "刻痕歪斜会让水珠只聚在杯底一小块，看似出了水却迟迟不滑落。干燥空气里施术者会感到指尖发凉而杯壁依旧干燥，强行加注魔力只会让刻痕发白，水珠却不再增多。",
      "counters": [
        "把杯子移到干燥处或用布擦干杯壁，水汽便无从凝结。",
        "用温水冲淋杯壁，使刻痕温度接近空气，凝露速度大幅下降。"
      ],
      "socialConsequences": "赶路者和守夜人乐意用它在清晨凑出几口水，卖水的小贩却担心路人不再光顾。客栈掌柜通常只允许在客房内对自家杯子施术，若在井边或水摊旁反复凝露，会被怀疑抢占别人生计。乡约见证的借杯场合里，施术者往往先说明水只够解渴，不替代买水。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时水珠零星挂在杯壁，需等待较长时间才够一口。",
        "环线稳定后，潮湿天气里能较快凝出半杯清水。",
        "熟练者会先判断空气湿度，避免在干燥处白费魔力。",
        "更高熟练度只让出水更均匀可靠，水量仍受空气湿度限制。"
      ]
    },
    {
      "id": "spell_water_02",
      "theory": "净水术令魔力在一桶水中缓慢扩散，带动悬浮的泥沙、草屑和虫尸彼此靠近，结成絮团后沉向桶底。它只处理肉眼可见的悬浮污物，溶于水的毒物、盐分和看不见的病气都不受影响。水质太浑时絮团过多，需分次施术并换水，否则沉淀层会被再次搅起。",
      "casting": "双掌虚按桶口两侧，沿桶沿由外向内画两个同心圆，同时低声数息，待水面出现第一圈浑浊涟漪。",
      "failure": "魔力送入过快会让整桶水翻涌，絮团被重新打散，水反而比先前更浑。若桶壁有裂缝，魔力会沿裂缝外泄，水面只微微发暗，泥沙依旧悬浮，施术者常误以为水已变清。",
      "counters": [
        "往水中撒一把粗砂并搅动，可让絮团提前松散上浮。",
        "把桶换成浅底宽口容器，沉淀层容易被看穿并重新搅浑。"
      ],
      "socialConsequences": "船工和挑夫在取河水后常请人净化一桶，再煮沸饮用。卖炭人与陶匠会顺势推销滤布和沉淀缸，而专营净水药粉的商贩则担心术法抢走生意。港务规定追究货损时，若有人声称用净水术处理过受污饮水，须说明它不能消除一切毒素，以免延误就医。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时只能澄清表层，桶底仍留有明显泥絮。",
        "手法稳定后能一次沉淀大半悬浮污物，水色转浅。",
        "熟练者懂得分次施术，避免絮团重新翻起。",
        "更高熟练度只提高澄清均匀度，对溶解毒素仍无作用。"
      ]
    },
    {
      "id": "spell_water_03",
      "theory": "辨泉术将魔力送入手心浅纹，再贴近水面或湿土，使纹路对盐分与腐败气味产生细微刺感。刺感越尖锐，说明水中盐分或腐物越多。它只反映近处水源的粗略状况，不能探出暗藏契约、诅咒或人为下毒，也不能判断水是否含有看不见的病气，因此老练的取水人仍会煮沸后再用。",
      "casting": "单膝跪在水边，掌心朝下悬于水面一拳处，另一手在腕上轻画短线，闭眼感受掌心纹路的刺麻变化。",
      "failure": "掌心贴得太近会沾上水面浮沫，刺感被误读为盐分高。若周围有腐草或死水，魔力会同时受多方气味干扰，纹路忽麻忽木，让人误判整片水源都不能饮用。",
      "counters": [
        "在水面撒一层干净细沙，可隔开浮沫与掌心纹路的接触。",
        "点燃一小束干草，让烟味盖过腐气，可干扰施术者的判断。"
      ],
      "socialConsequences": "商队在扎营前会请人辨泉，再决定是否让牲口饮用。卖盐的贩子不喜欢有人当众测出井水偏咸，恐影响生意；而陶匠和煮盐户则借机说明咸水另有用途。乡约见证的取水约定里，若一方声称某泉已腐，另一方可以要求换人再辨，避免误判导致整村弃用一口好井。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "consent"
      },
      "proficiencyEffects": [
        "低熟练度时只能感到大致刺麻，分不清盐分与腐气。",
        "手法稳定后能区分水偏咸还是带腐味。",
        "熟练者会避开浮沫和腐草，减少误判。",
        "更高熟练度只让判断更准，仍探不出暗藏契约与毒素。"
      ]
    }
  ]
}
